    self,
    console: "Console",
    renderables: Iterable["ConsoleRenderable"],
    log_time: Optional[datetime] = None,
    time_format: Optional[Union[str, FormatTimeCallable]] = None,
    level: TextType = "",
    path: Optional[str] = None,
    line_no: Optional[int] = None,
